import { Button } from '@refy-design/web';
import { Command } from '@refy-design/web';
import type { CommandItem } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { createContext } from 'react';
import type { RefObject } from 'react';
import { useContext } from 'react';
import { useEffect } from 'react';
import { useState } from 'react';
const ExampleScope = createContext<RefObject<HTMLDivElement | null> | null>(null);
function useCommandShortcut(onOpen: () => void, enabled = true) {
  const scope = useContext(ExampleScope);
  useEffect(() => {
    if (!enabled) return;
    const onKey = (event: KeyboardEvent) => {
      if (
        event.defaultPrevented ||
        (scope && !scope.current?.contains(event.target as Node))
      )
        return;
      if (event.key.toLowerCase() === 'k' && (event.metaKey || event.ctrlKey)) {
        event.preventDefault();
        onOpen();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [scope, onOpen, enabled]);
}
